static void GoMenu(void) { screen = fromWorld ? SCR_WORLD : SCR_MENU; scroll = 0; }
static int quizPick[3] = { -1, -1, -1 };      /* what was picked for each question of the quiz being taken */
static char quizTypedTxt[3][64];
