    for (int i = 0; i < 6; i++) {
        Txt(fBold, TextFormat("%s  -  %ds", FCROP[i].name, FCROP[i].grow), x, y, 15, WHITE); y += 20;
        y += Wrapped(fReg, TextFormat("Costs %s. %s.", FCROP[i].cost, FCROP[i].gives), x + 10, y, w - 10, 13, (Color) { 190, 196, 212, 255 }); y += 8;
    }
